-- Reframe schema, generated by reframe/db/build_schema.py. Do not edit by hand.
-- user_version = 1

CREATE TABLE item (
  id            TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  kind          TEXT NOT NULL DEFAULT 'plan' CHECK (kind IN ('plan','log')),
  title         TEXT NOT NULL CHECK (length(trim(title)) > 0),
  start_date    TEXT NOT NULL CHECK (date(start_date) IS start_date),
  end_date      TEXT NOT NULL CHECK (date(end_date)   IS end_date),
  notes         TEXT NOT NULL DEFAULT '',
  origin        TEXT NOT NULL DEFAULT 'local' CHECK (origin IN ('local','outlook')),
  outlook_uid   TEXT UNIQUE,
  outlook_series_id TEXT,
  outlook_calendar TEXT,
  outlook_time  TEXT,
  outlook_location TEXT,
  deleted_at    TEXT,
  hidden_at     TEXT,
  created_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at    TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (end_date >= start_date)
);
CREATE INDEX item_dates ON item (start_date, end_date)
  WHERE deleted_at IS NULL AND hidden_at IS NULL;
CREATE INDEX item_series ON item (outlook_series_id) WHERE outlook_series_id IS NOT NULL;

CREATE TABLE outlook_hidden_series (
  series_id TEXT PRIMARY KEY,
  hidden_at TEXT NOT NULL
);

-- norm_key is a generated column (R-41): agents only supply name, and two tags
-- whose names normalize to the same key cannot coexist.
CREATE TABLE tag (
  id         TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  name       TEXT NOT NULL CHECK (length(trim(name)) > 0),
  norm_key   TEXT GENERATED ALWAYS AS (trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(lower(name), '!', ' '), '"', ' '), '#', ' '), '$', ' '), '%', ' '), '&', ' '), '''', ' '), '(', ' '), ')', ' '), '*', ' '), '+', ' '), ',', ' '), '-', ' '), '.', ' '), '/', ' '), ':', ' '), ';', ' '), '<', ' '), '=', ' '), '>', ' '), '?', ' '), '@', ' '), '[', ' '), '\', ' '), ']', ' '), '^', ' '), '_', ' '), '`', ' '), '{', ' '), '|', ' '), '}', ' '), '~', ' '), char(9), ' '), char(10), ' '), char(13), ' '), '  ', ' <>'), '<> ', ''), '<>', ''))) STORED NOT NULL UNIQUE CHECK (norm_key <> ''),
  color_slot INTEGER CHECK (color_slot IS NULL OR color_slot BETWEEN 0 AND 15),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE item_tag (
  item_id  TEXT NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  tag_id   TEXT NOT NULL REFERENCES tag(id)  ON DELETE CASCADE,
  position INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (item_id, tag_id)
);
CREATE INDEX item_tag_tag ON item_tag (tag_id);

CREATE TABLE outlook_series_tag (
  series_id TEXT NOT NULL,
  tag_id    TEXT NOT NULL REFERENCES tag(id) ON DELETE CASCADE,
  position  INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (series_id, tag_id)
);

CREATE TABLE attachment (
  id         TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  item_id    TEXT NOT NULL REFERENCES item(id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('file','url')),
  target     TEXT NOT NULL,
  label      TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX attachment_item ON attachment (item_id);

CREATE TABLE change_set (
  id     INTEGER PRIMARY KEY AUTOINCREMENT,
  ts     TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  actor  TEXT NOT NULL CHECK (actor IN ('user','agent','sync','undo','external')),
  label  TEXT NOT NULL,
  reverts_change_set_id INTEGER REFERENCES change_set(id)
);

CREATE TABLE change (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  change_set_id INTEGER REFERENCES change_set(id),
  ts            TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  table_name    TEXT NOT NULL,
  row_key       TEXT NOT NULL,
  op            TEXT NOT NULL CHECK (op IN ('insert','update','delete')),
  before_json   TEXT,
  after_json    TEXT
);
CREATE INDEX change_set_idx ON change (change_set_id);
CREATE INDEX change_row_idx ON change (table_name, row_key);

CREATE TABLE app_context (
  id            INTEGER PRIMARY KEY CHECK (id = 1),
  actor         TEXT NOT NULL DEFAULT 'external',
  change_set_id INTEGER
);
INSERT INTO app_context (id) VALUES (1);

CREATE TABLE setting (key TEXT PRIMARY KEY, value TEXT NOT NULL);

CREATE TABLE sync_run (
  id INTEGER PRIMARY KEY AUTOINCREMENT, started_at TEXT NOT NULL, finished_at TEXT,
  calendars TEXT, added INTEGER, updated INTEGER, removed INTEGER, status TEXT, error TEXT
);

-- Read-only convenience view for agents and reports (excludes deleted and hidden items)
CREATE VIEW v_item AS
SELECT i.id, i.kind, i.title, i.start_date, i.end_date, i.notes, i.origin,
       (SELECT group_concat(t.name, '; ' ORDER BY it.position, t.name)
          FROM item_tag it JOIN tag t ON t.id = it.tag_id
         WHERE it.item_id = i.id) AS tags
FROM item i WHERE i.deleted_at IS NULL AND i.hidden_at IS NULL;

CREATE TRIGGER trg_item_ai AFTER INSERT ON item BEGIN
  INSERT INTO change (change_set_id, table_name, row_key, op, before_json, after_json)
  VALUES ((SELECT change_set_id FROM app_context WHERE id = 1), 'item', NEW.id, 'insert', NULL, json_object('id', NEW.id, 'kind', NEW.kind, 'title', NEW.title, 'start_date', NEW.start_date, 'end_date', NEW.end_date, 'notes', NEW.notes, 'origin', NEW.origin, 'outlook_uid', NEW.outlook_uid, 'outlook_series_id', NEW.outlook_series_id, 'outlook_calendar', NEW.outlook_calendar, 'outlook_time', NEW.outlook_time, 'outlook_location', NEW.outlook_location, 'deleted_at', NEW.deleted_at, 'hidden_at', NEW.hidden_at, 'created_at', NEW.created_at, 'updated_at', NEW.updated_at));
END;

