-- The log is protected in the database itself (spec 5.3).
CREATE TRIGGER trg_change_bu BEFORE UPDATE ON change
WHEN NOT (OLD.change_set_id IS NULL AND NEW.change_set_id IS NOT NULL
          AND NEW.id = OLD.id AND NEW.ts = OLD.ts AND NEW.table_name = OLD.table_name
          AND NEW.row_key = OLD.row_key AND NEW.op = OLD.op
          AND NEW.before_json IS OLD.before_json AND NEW.after_json IS OLD.after_json)
BEGIN SELECT RAISE(ABORT, 'change is append-only'); END;

CREATE TRIGGER trg_change_bd BEFORE DELETE ON change
BEGIN SELECT RAISE(ABORT, 'change is append-only'); END;

CREATE TRIGGER trg_change_set_bu BEFORE UPDATE ON change_set
WHEN NOT (OLD.id IS (SELECT change_set_id FROM app_context WHERE id = 1)
          AND NEW.id = OLD.id AND NEW.ts = OLD.ts AND NEW.actor = OLD.actor
          AND NEW.reverts_change_set_id IS OLD.reverts_change_set_id)
BEGIN SELECT RAISE(ABORT, 'change_set is append-only (only the open set label may change)'); END;

CREATE TRIGGER trg_change_set_bd BEFORE DELETE ON change_set
BEGIN SELECT RAISE(ABORT, 'change_set is append-only'); END;

CREATE TRIGGER trg_item_lock_bu BEFORE UPDATE ON item
WHEN OLD.origin = 'outlook'
 AND (SELECT actor FROM app_context WHERE id = 1) NOT IN ('sync', 'undo')
 AND (OLD.title IS NOT NEW.title OR OLD.start_date IS NOT NEW.start_date
      OR OLD.end_date IS NOT NEW.end_date OR OLD.origin IS NOT NEW.origin
      OR OLD.outlook_uid IS NOT NEW.outlook_uid OR OLD.outlook_series_id IS NOT NEW.outlook_series_id
      OR OLD.outlook_calendar IS NOT NEW.outlook_calendar OR OLD.outlook_time IS NOT NEW.outlook_time
      OR OLD.outlook_location IS NOT NEW.outlook_location)
BEGIN SELECT RAISE(ABORT, 'Imported from Outlook: core fields are locked'); END;

CREATE TRIGGER trg_item_nodelete_bd BEFORE DELETE ON item
WHEN (SELECT actor FROM app_context WHERE id = 1) <> 'undo'
BEGIN SELECT RAISE(ABORT, 'Hard delete is not allowed: set deleted_at instead'); END;
